from train_carla_nav_recovery_factorial512 import *
from interaction_flow import InteractionFlow
from carla_nav_contract import cache_near

def main():
 safe_idle();configure_runtime();out=ROOT/'artifacts/carla-fm-signal-frozen';out.mkdir(exist_ok=True);base=ROOT/'artifacts/carla-interaction-paired512';ckpath=base/'2060-interaction/latest.ckpt';sha=hashlib.sha256(ckpath.read_bytes()).hexdigest();ck=torch.load(ckpath,map_location='cpu',weights_only=False);m=InteractionFlow(True);m.load_state_dict({k[6:]:v for k,v in ck['state_dict'].items() if k.startswith('model.')});cfg=ck['task_state']['settings']['objective'];del ck;m.cuda().eval();m.teacher.requires_grad_(False);rec=json.loads((ROOT/'data/carla_recovery_combined_v2/manifest.json').read_text());names=[p for ep in [0,1] for idx in [50,80,100,200] for p in rec['train'] if Path(p).parent.name==f'episode{ep}' and int(Path(p).stem)==idx];NavData.enabled=True;ds=NavData(names);b=batch_to([ds[i] for i in range(len(ds))],'cuda');target=m.to_flow_space(b,b['trajectory']).detach();torch.manual_seed(2800);noise=torch.randn(4,25,5,device='cuda')[...,:2].repeat(2,1,1);swap=torch.arange(8,device='cuda').roll(4);params=[p for p in m.parameters() if p.requires_grad];rows=[]
 def gradrow(loss):
  gs=torch.autograd.grad(loss,params,retain_graph=True,allow_unused=True);squares=sum(float(g.float().square().sum()) for g in gs if g is not None);w=next(g for p,g in zip(params,gs) if p is m.state[0].weight);ow=next(g for p,g in zip(params,gs) if p is m.output.weight);return {'global_norm':squares**.5,'state_col_norms':{str(i):float(w[:,i].norm()) if w is not None else 0. for i in [0,5,19]},'output_norm':float(ow.norm()) if ow is not None else 0.}
 for tv in [.05,.25,.5,.75,.95]:
  t=torch.full((8,1),tv,device='cuda');x=(1-tv)*noise+tv*target;pred=m(b,x,t).float();err=pred-(target-noise);phys=m.from_flow_space(b,x+(1-tv)*pred);e=(phys[:,:,:2]-b['trajectory'][:,:,:2])*pred.new_tensor([50,10]);pos=F.smooth_l1_loss(e/cfg['position_scale_m'],torch.zeros_like(e))*(0 if tv<cfg['auxiliary_min_t'] else 1/(1-cfg['auxiliary_min_t']))*cfg['weights']['position'];wx=m.auxiliary_loss(b);terms={'fm_x':.5*err[:,:,0].square().mean(),'fm_y':.5*err[:,:,1].square().mean(),'weighted_position':pos,'weighted_world':.1*sum(wx)};grads={k:gradrow(v) for k,v in terms.items()};total=sum(terms.values());grads['total']=gradrow(total)
  with torch.no_grad():
   z={**b,'state':b['state'].clone()};z['state'][:,4:6]=b['state'][swap,4:6];sp=m(z,x,t).float();zero={**b,'state':b['state'].clone()};zero['state'][:,4:6]=0;zp=m(zero,x,t).float();expected=target-target[swap];actual=pred-sp;mask=torch.tensor([False,True,True,False]*2,device='cuda');a=actual[mask,:,1];g=expected[mask,:,1];cos=float((a*g).sum()/(a.norm()*g.norm()).clamp_min(1e-12));field_endpoint_y=(x+(1-tv)*pred)[:,:,1];rows.append({'t':tv,'loss':{k:float(v.detach()) for k,v in terms.items()},'gradients':grads,'clip1_coefficient':min(1,1/max(grads['total']['global_norm'],1e-12)),'nav_swap_delta_rms_y':float(a.square().mean().sqrt()),'opposite_target_delta_rms_y':float(g.square().mean().sqrt()),'delta_target_cosine':cos,'zero_nav_loss_delta':float(F.mse_loss(zp,target-noise)-F.mse_loss(pred,target-noise)),'target_q_rms_xy':target.square().mean((0,1)).sqrt().cpu().tolist(),'noise_rms_xy':noise.square().mean((0,1)).sqrt().cpu().tolist(),'conditional_endpoint_q_y_rmse':float((field_endpoint_y-target[:,:,1]).square().mean().sqrt()),'zero_endpoint_q_y_rmse':float(target[:,:,1].square().mean().sqrt())})
  del pred,total,terms,wx,phys,e,pos
 assert sha==hashlib.sha256(ckpath.read_bytes()).hexdigest();(out/'report.json').write_text(json.dumps({'names':names,'objective':cfg,'rows':rows,'limits':'8 train windows,4 mirror-shared Gaussian noises; eval-mode FP32 frozen weights. Counterfactual swaps at fixed bridge x contain targetinfo as permitted trainingdiagnostic, not onlineinput. Swapped actual target includes pose/history differences, expected delta is reference not exact counterfactualtruth. No updates/test/closedloop.'},indent=2));print('DONE')
